ch as (
 insert into public.academy_chapters(course_id,title,description,sort_order,published)
 select id,'علم المناخ وتحليل البيانات المناخية','أساسيات المناخ والدوران العام والأنظمة الجوية وتحليل السجلات والتطرف المناخي.',8,false from c
 on conflict(course_id,title) do update set description=excluded.description returning id,course_id
),
u1 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'أساسيات علم المناخ','عناصر المناخ ومحدداته ومصادر البيانات والمعدلات المناخية.',1,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
u2 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'الدوران العام والمناطق المناخية','ميزانية الطاقة والدوران العام وأحزمة الضغط والرياح.',2,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
u3 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'الأنظمة الجوية المؤثرة في المناخ','الكتل الهوائية والجبهات والمنخفضات والمرتفعات.',3,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
u4 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'تحليل البيانات والسلاسل المناخية','جودة البيانات والتجانس والاتجاهات والتذبذب.',4,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
u5 as (insert into public.academy_units(chapter_id,title,description,sort_order,published) select id,'التطرف المناخي ومخاطره','مؤشرات التطرف والجفاف وموجات الحر.',5,false from ch on conflict(chapter_id,title) do update set description=excluded.description returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values
('introduction-to-climatology','مقدمة في علم المناخ وعناصره','مدخل إلى علم المناخ ومكوناته ومقاييسه ومصادر بياناته والتمييز بين الطقس والمناخ.','{"blocks":[{"type":"heading","text":"ما علم المناخ؟"},{"type":"text","text":"علم المناخ هو دراسة سلوك الغلاف الجوي والأنظمة المناخية على مدد زمنية طويلة نسبياً، بما يشمل المتوسطات والتباين والتطرف والتغير. لا يقتصر على متوسط درجة الحرارة، بل يشمل تفاعل الغلاف الجوي والمحيطات واليابسة والجليد والغلاف الحيوي."},{"type":"heading","text":"الطقس والمناخ"},{"type":"text","text":"الطقس يصف حالة الغلاف الجوي خلال مدد قصيرة مثل الساعات والأيام، أما المناخ فيصف التوزيع الإحصائي لحالات الطقس على مدى طويل، بما في ذلك المتوسطات والتشتت والتكرار والقيم المتطرفة."},{"type":"heading","text":"عناصر المناخ"},{"type":"list","items":["درجة حرارة الهواء والسطح.","الضغط الجوي والرياح واتجاهاتها.","الرطوبة والتبخر والهطول.","الإشعاع الشمسي والغطاء السحابي.","الرؤية والظواهر الجوية عند دراستها مناخياً."]},{"type":"heading","text":"العوامل المتحكمة بالمناخ"},{"type":"list","items":["خط العرض وزاوية سقوط الإشعاع الشمسي.","الارتفاع والتضاريس واتجاه السفوح.","القرب من البحار والتيارات البحرية.","الدوران العام والكتل الهوائية.","الغطاء الأرضي واستخدامات الأراضي."]},{"type":"heading","text":"المعدلات المناخية"},{"type":"text","text":"تستخدم المعدلات المناخية لوصف الظروف المعتادة خلال فترة مرجعية محددة. من الشائع استخدام فترة ثلاثين سنة للمعدلات المناخية القياسية، مع توثيق الفترة المرجعية ومصدر البيانات وطريقة الحساب."},{"type":"heading","text":"المتوسط لا يصف كل شيء"},{"type":"text","text":"قد يتساوى متوسط الهطول السنوي في موقعين بينما يختلف توزيع المطر بين الفصول وعدد الأيام الممطرة وشدة الحالات. لذلك ينبغي دراسة التوزيع والتباين والتطرف إلى جانب المتوسط."},{"type":"heading","text":"مصادر البيانات المناخية"},{"type":"list","items":["سجلات محطات الرصد السطحي.","السبرات وقياسات طبقات الجو العليا.","بيانات الأقمار الصناعية وإعادة التحليل.","سجلات المحيطات والبحار والغطاء الأرضي.","مخرجات النماذج المناخية وبيانات الرصد الشبكية."]},{"type":"callout","text":"لا تقارن معدلين مناخيين قبل التأكد من تطابق الفترة المرجعية وتعريف المتغير وجودة البيانات وموقع المحطة."},{"type":"example","text":"مثال: عند مقارنة مناخ مدينتين، افحص متوسط الحرارة الشهري والهطول الموسمي وعدد الأيام الممطرة والمدى الحراري، مع توثيق الارتفاع والفترة المرجعية لكل محطة."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"علم المناخ يدرس المتوسطات والتباين والتطرف والتغير ضمن نظام مترابط. وتبدأ الدراسة الصحيحة ببيانات موثقة وفترة مرجعية واضحة."}]}',300,40,'["التمييز بين الطقس والمناخ والمناخات المحلية","شرح عناصر المناخ ومحدداته","التعرف إلى مصادر البيانات والمعدلات المناخية"]','أساسيات علم المناخ'),
('global-climate-and-general-circulation','المناخ العالمي وأنظمة الدوران العام','فهم ميزانية الطاقة والدوران العام للغلاف الجوي والخلايا المدارية وأحزمة الضغط والرياح.','{"blocks":[{"type":"heading","text":"ميزانية الطاقة الأرضية"},{"type":"text","text":"تتلقى الأرض طاقة شمسية قصيرة الموجة وتعيد إصدار طاقة طويلة الموجة. يختلف التسخين باختلاف خط العرض والفصول والغطاء السحابي والسطح، وينقل الغلاف الجوي والمحيط جزءاً من فائض الطاقة في العروض المنخفضة نحو العروض العليا."},{"type":"heading","text":"الدوران العام"},{"type":"text","text":"الدوران العام هو النمط واسع النطاق لحركة الهواء الناتج عن التسخين غير المتساوي ودوران الأرض وتوزيع اليابسة والمحيطات. يتغير مكان وشدة مراكز الضغط والأحزمة الريحية مع الفصول."},{"type":"heading","text":"خلايا الدوران"},{"type":"list","items":["خلية هادلي: صعود هواء مداري وهبوط نسبي في نطاقات شبه مدارية.","خلية فيريل: دوران متوسط العروض يتأثر بالاضطرابات والدوامات الجوية.","الخلية القطبية: دوران في العروض العليا يرتبط بالهواء البارد والضغط القطبي."]},{"type":"heading","text":"أحزمة الضغط والرياح"},{"type":"text","text":"تظهر نطاقات ضغط منخفض استوائي وشبه مداري مرتفع وعروض منخفضة وضغط قطبي، لكنها ليست أحزمة ثابتة تماماً. تؤثر الفصول والقارات والمحيطات والاضطرابات الجوية في مواقعها."},{"type":"heading","text":"الرياح السائدة"},{"type":"text","text":"تنشأ الرياح التجارية والرياح الغربية والشرقية القطبية ضمن تفاعل تدرج الضغط ودوران الأرض والاحتكاك. تتغير شدتها واتجاهاتها محلياً بفعل التضاريس والأنظمة الجوية."},{"type":"heading","text":"التيار النفاث"},{"type":"text","text":"التيارات النفاثة نطاقات من الرياح القوية قرب التروبوبوز، ترتبط بتدرجات الحرارة الأفقية والدوران واسع النطاق. تؤثر في مسارات المنخفضات والجبهات ومناطق الرفع والهبوط."},{"type":"heading","text":"الموسمية"},{"type":"text","text":"تتحرك أحزمة الضغط والأمطار المدارية مع انتقال نطاق التسخين الأعظم بين نصفي الكرة. تسهم هذه الحركة في نشوء أنظمة موسمية مثل الرياح الموسمية، وتتباين آثارها إقليمياً."},{"type":"callout","text":"النموذج الثلاثي للخلايا تبسيط تعليمي للدوران العام؛ فالجو الحقيقي يتضمن دوامات واضطرابات وتفاعلات مع المحيط واليابسة."},{"type":"example","text":"مثال: لتفسير موسم مطير مداري، تتبع انتقال نطاق التقارب المداري، وتغير الرياح السطحية وتدفق الرطوبة ومناطق الصعود خلال أشهر السنة."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يساعد فهم ميزانية الطاقة والدوران العام على تفسير أحزمة الرياح والضغط والمناخات الإقليمية وانتقال الأمطار موسمياً."}]}',310,45,'["شرح ميزانية الطاقة الأرضية","تمييز خلايا هادلي وفيريل والخلية القطبية","تفسير أحزمة الضغط والرياح السائدة"]','الدوران العام والمناطق المناخية'),
('air-masses-fronts-and-climate-systems','الكتل الهوائية والجبهات والأنظمة المناخية','دراسة خصائص الكتل الهوائية والجبهات والمنخفضات والمرتفعات وتأثيرها في المناخ الإقليمي.','{"blocks":[{"type":"heading","text":"الكتلة الهوائية"},{"type":"text","text":"الكتلة الهوائية حجم واسع من الهواء تتقارب خصائصه الحرارية والرطوبية أفقياً نسبياً. تتحدد صفاتها من منطقة المصدر ومدة بقائها فوقها ومسار انتقالها والتعديلات التي تتعرض لها."},{"type":"heading","text":"تصنيف الكتل الهوائية"},{"type":"list","items":["قارية أو بحرية بحسب طبيعة سطح المصدر والرطوبة.","قطبية أو مدارية بحسب الخصائص الحرارية وموقع المصدر.","تتغير خصائص الكتلة خلال انتقالها فوق اليابسة أو البحر."]},{"type":"heading","text":"الجبهة الهوائية"},{"type":"text","text":"الجبهة منطقة انتقالية تفصل بين كتل هوائية مختلفة الخصائص. يرتبط مرورها بتغيرات في الحرارة والرياح والضغط والسحب والهطول، وتختلف الاستجابة حسب استقرار الهواء والرطوبة وسرعة الحركة."},{"type":"heading","text":"أنواع الجبهات"},{"type":"list","items":["الجبهة الباردة: يتقدم الهواء الأبرد ويدفع الهواء الدافئ إلى أعلى.","الجبهة الدافئة: يتقدم الهواء الدافئ فوق هواء أبرد بصورة تدريجية غالباً.","الجبهة الثابتة: حركة الجبهة محدودة نسبياً.","الجبهة المسدودة: تلتحق الجبهة الباردة بالدافئة ضمن تطور المنخفض."]},{"type":"heading","text":"المنخفضات والمرتفعات"},{"type":"text","text":"ترتبط المنخفضات غالباً بالتقارب والصعود والاضطرابات، بينما ترتبط المرتفعات في كثير من الحالات بالهبوط والاستقرار النسبي. لكن الأثر الفعلي يعتمد على البنية الرأسية والرطوبة والموسم والتضاريس."},{"type":"heading","text":"الأنظمة شبه المدارية والموسمية"},{"type":"text","text":"تؤثر المرتفعات شبه المدارية والمنخفضات الموسمية والأخاديد العلوية في توزيع الحرارة والهطول والرياح. وقد يتغير تأثير النظام نفسه باختلاف موقعه وقوته وتفاعله مع الأنظمة المجاورة."},{"type":"heading","text":"من الطقس إلى المناخ"},{"type":"text","text":"يسهم تكرار مسارات المنخفضات والجبهات والكتل الهوائية في تشكيل خصائص المناخ الإقليمي. لذلك تدرس خرائط التكرار الموسمي ومؤشرات الأنظمة الجوية إلى جانب متوسطات العناصر المناخية."},{"type":"callout","text":"لا يكفي اسم الكتلة الهوائية أو الجبهة وحده لتحديد الطقس؛ يجب تحليل الرطوبة والاستقرار والرفع والبنية الرأسية وموقع النظام."},{"type":"example","text":"مثال: لدراسة أثر تكرار الجبهات الباردة في موسم ما، احسب عدد الحالات ومساراتها وتوزيع الهطول وتغير الحرارة، ثم قارن النتائج بمواسم أخرى مع مراعاة جودة السجلات."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"تساعد الكتل الهوائية والجبهات والأنظمة الضغطية على تفسير تغير الطقس، كما أن تكرارها ومساراتها يتركان بصمة في مناخ المناطق."}]}',320,45,'["تصنيف الكتل الهوائية بحسب مصدرها وخصائصها","شرح أنواع الجبهات والتغيرات المصاحبة لها","ربط تكرار الأنظمة الجوية بالخصائص المناخية الإقليمية"]','الأنظمة الجوية المؤثرة في المناخ'),
('climate-time-series-and-trends','تحليل السلاسل الزمنية المناخية والاتجاهات','تنظيم السجلات المناخية وفحص جودتها وتحليل التغيرات والاتجاهات والدورية.','{"blocks":[{"type":"heading","text":"ما السلسلة الزمنية المناخية؟"},{"type":"text","text":"السلسلة الزمنية مجموعة قياسات مرتبة زمنياً لمتغير مثل الحرارة أو الهطول أو الرطوبة. قد تكون يومية أو شهرية أو سنوية، ويحدد تواترها نوع التحليل الممكن."},{"type":"heading","text":"إعداد البيانات"},{"type":"list","items":["توثيق المحطة والإحداثيات والارتفاع وأداة القياس.","فحص القيم المفقودة والتكرارات والوحدات.","اكتشاف القيم الشاذة ومراجعة السجلات الأصلية.","توحيد التوقيت وفترات التجميع والتعريفات.","توثيق أي نقل للمحطة أو تغيير للأجهزة."]},{"type":"heading","text":"التجانس المناخي"},{"type":"text","text":"قد تؤدي تغييرات موقع المحطة أو أجهزتها أو بيئتها إلى قفزات غير مناخية في السجل. يهدف اختبار التجانس إلى تحديد الانقطاعات المحتملة ومقارنتها بمحطات مرجعية أو معلومات وصفية."},{"type":"heading","text":"الاتجاه والتذبذب"},{"type":"text","text":"الاتجاه يصف تغيراً طويل الأمد في السلسلة، بينما تمثل التذبذبات تقلبات على مدد أقصر أو دورات متكررة. قد يتداخل الاتجاه مع التغيرات الموسمية والسنوية والتباين الطبيعي."},{"type":"heading","text":"المتوسطات والشذوذ"},{"type":"text","text":"الشذوذ هو الفرق بين قيمة الفترة وقيمة مرجعية مناسبة. يجب ذكر الفترة المرجعية وطريقة التجميع؛ فالشذوذ الشهري لا يساوي التغير السنوي، وقد تخفي المتوسطات اختلافات بين الفصول."},{"type":"heading","text":"تقدير الاتجاه"},{"type":"text","text":"يمكن استخدام الانحدار الخطي لتقدير ميل أولي، أو طرائق متينة مثل تقدير Sen، مع اختبار دلالة مناسب مثل Mann-Kendall عند تحقق شروط استخدامه. الدلالة الإحصائية لا تعني تلقائياً أهمية عملية أو سبباً محدداً."},{"type":"heading","text":"الموسمية والارتباط الذاتي"},{"type":"text","text":"تتضمن السلاسل المناخية موسمية وارتباطاً بين القيم المتجاورة. تجاهل هذه الخصائص قد يؤدي إلى تقدير غير صحيح لعدم اليقين ودلالة الاتجاه. اختر طريقة تراعي بنية البيانات."},{"type":"heading","text":"عرض النتائج"},{"type":"list","items":["اعرض عدد السنوات ونسبة اكتمال البيانات.","اذكر الفترة المرجعية ووحدة الميل.","بيّن طريقة معالجة القيم المفقودة والانقطاعات.","اعرض عدم اليقين وحدود التفسير.","استخدم رسماً زمنياً ومحاور ووحدات واضحة."]},{"type":"callout","text":"لا تستنتج تغيراً مناخياً من مقارنة سنتين أو من محطة واحدة دون فحص طول السجل وجودته وتمثيله المكاني."},{"type":"example","text":"مثال: لتحليل الحرارة الشهرية خلال عدة عقود، افحص تجانس السجل أولاً، ثم احسب الشذوذ بالنسبة إلى فترة مرجعية معلنة، وقدّر الميل مع فاصل عدم يقين وافحص التغير الموسمي."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"تحليل السلاسل المناخية يبدأ بجودة البيانات وتجانسها، ثم فصل الاتجاه عن التذبذب والموسمية، وعرض النتيجة مع عدم اليقين."}]}',330,45,'["إعداد سلسلة زمنية مناخية موثوقة","تمييز الاتجاه طويل الأمد عن التذبذب والدورية","شرح مبادئ التجانس الإحصائي وتقييم الاتجاه"]','تحليل البيانات والسلاسل المناخية'),
('climate-extremes-drought-and-heatwaves','التطرف المناخي ومؤشرات الجفاف والموجات الحرارية','مفاهيم التطرف المناخي ومؤشرات الحرارة والهطول والجفاف ومبادئ تفسير المخاطر.','{"blocks":[{"type":"heading","text":"ما التطرف المناخي؟"},{"type":"text","text":"التطرف المناخي حدث أو قيمة تقع قرب أطراف التوزيع الإحصائي لمتغير مناخي، أو تتجاوز عتبة محددة. يعتمد تعريف التطرف على المتغير والفترة المرجعية والموسم والمنطقة."},{"type":"heading","text":"القيم القصوى والعتبات"},{"type":"text","text":"يمكن تعريف التطرف باستخدام المئينات أو عتبات ثابتة أو مدد استمرار. يجب تحديد هل القياس يومي أم شهري، وهل الحدث يعتمد على تجاوز قيمة أم استمرارها عدة أيام."},{"type":"heading","text":"موجات الحر"},{"type":"text","text":"موجة الحر فترة من درجات حرارة مرتفعة على نحو غير معتاد بالنسبة إلى المناخ المحلي والموسم، وقد تشمل الحرارة الليلية والرطوبة. تختلف التعريفات التشغيلية بين الجهات، لذا يجب ذكر معيار الجهة المستخدمة."},{"type":"heading","text":"مؤشرات الحرارة"},{"type":"list","items":["المئينات العليا لدرجة الحرارة القصوى أو الدنيا.","عدد الأيام أو الليالي التي تتجاوز عتبة محددة.","مدة الموجة الحرارية وشدتها التراكمية.","مؤشرات تجمع الحرارة النهارية والليلية وفق تعريف معلن."]},{"type":"heading","text":"الجفاف وأنواعه"},{"type":"text","text":"الجفاف ظاهرة متعددة الأبعاد، وقد يكون أرصادياً بسبب نقص الهطول، أو زراعياً بسبب نقص رطوبة التربة، أو هيدرولوجياً بسبب انخفاض الجريان والمخزون المائي. لا تتطور الأنواع بالسرعة نفسها."},{"type":"heading","text":"مؤشرات الجفاف"},{"type":"list","items":["SPI: مؤشر الهطول القياسي على مدد تجميع مختلفة.","SPEI: يضيف أثر الطلب التبخري المناخي إلى ميزان الهطول.","مؤشرات رطوبة التربة لمتابعة الجفاف الزراعي.","مؤشرات الجريان والخزانات لمتابعة الجفاف الهيدرولوجي."]},{"type":"heading","text":"التطرف المطري"},{"type":"text","text":"يمكن تحليل شدة الهطول اليومي أو عدد الأيام شديدة المطر أو فترات الجفاف المتصلة. يجب الانتباه إلى جودة مقاييس المطر وتغير مواقع المحطات وتأثير التضاريس."},{"type":"heading","text":"من المؤشر إلى المخاطر"},{"type":"text","text":"لا يساوي المؤشر المناخي وحده مستوى الخطر. يتشكل الخطر من تفاعل الظاهرة مع التعرض والهشاشة والقدرة على التكيف. لذلك ينبغي ربط المؤشرات بالزراعة والمياه والصحة والبنية التحتية وفق بيانات القطاع."},{"type":"callout","text":"لا تستخدم عتبة عالمية واحدة لموجة الحر أو الجفاف دون مراعاة المناخ المحلي والفصل وتعريف الجهة المختصة."},{"type":"example","text":"مثال: لمتابعة الجفاف، احسب SPI لفترات 1 و3 و6 أشهر، وقارنه بمؤشرات رطوبة التربة والجريان. اختلاف المؤشرات قد يعكس اختلاف مراحل الجفاف لا خطأً في أحدها بالضرورة."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"تحتاج دراسة التطرف والجفاف وموجات الحر إلى تعريفات ومؤشرات موثقة وفترات مرجعية مناسبة، ثم تفسير النتائج ضمن التعرض والهشاشة المحلية."}]}',340,45,'["تعريف التطرف المناخي وموجات الحر والجفاف","التعرف إلى مؤشرات شائعة للحرارة والهطول والجفاف","تفسير المؤشرات ضمن السياق المحلي وعدم اليقين"]','التطرف المناخي ومخاطره')
)
insert into public.academy_lessons
(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,
case d.unit when 'أساسيات علم المناخ' then u1.id when 'الدوران العام والمناطق المناخية' then u2.id when 'الأنظمة الجوية المؤثرة في المناخ' then u3.id when 'تحليل البيانات والسلاسل المناخية' then u4.id else u5.id end,
d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'علم المناخ وتحليل البيانات المناخية',d.unit
from d cross join c cross join ch cross join u1 cross join u2 cross join u3 cross join u4 cross join u5
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;